TEAM = {"billing@shop.example"}  # the support team's own address


def gate(tool, arg, ticket):
    """Decide in code whether a call the model proposed runs: "ran", "blocked" or "held"."""
    if tool == "lookup_account":
        return "ran" if arg == ticket["account"] else "blocked"
    if tool == "send_email":
        return "ran" if arg in {ticket["from"]} | TEAM else "held"
    return "blocked"  # a tool this gate does not know is denied by default
